#!/usr/bin/env node
import { greet } from './index.js';

const usage = 'Usage: greenfield-proof [name]\n       greenfield-proof --help';
const args = process.argv.slice(2);
if (args.length === 1 && args[0] === '--help') {
  console.log(usage);
} else if (args.length > 1 || args.some(arg => arg.startsWith('-'))) {
  console.error(usage);
  process.exitCode = 1;
} else {
  try {
    console.log(greet(args[0]));
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    console.error(usage);
    process.exitCode = 1;
  }
}


FILE test/greeting.test.mjs SHA256 1075d6995f910602ecbbf9f192bc6e07cd4f08814eebf16d5e5f31d9c46d4620
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { greet } from 'greenfield-proof';

const usage = 'Usage: greenfield-proof [name]\n       greenfield-proof --help\n';
const cli = fileURLToPath(new URL('../dist/cli.js', import.meta.url));
function run(args) {
  const result = spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8', timeout: 5000 });
  assert.equal(result.error, undefined);
  assert.equal(result.signal, null);
  return result;
}
test('public API defaults and preserves supplied nonblank names', () => {
  assert.equal(greet(), 'Hello, world!');
  assert.equal(greet(undefined), 'Hello, world!');
  assert.equal(greet('Ada'), 'Hello, Ada!');
  assert.equal(greet('世界'), 'Hello, 世界!');
  assert.equal(greet(' Ada '), 'Hello,  Ada !');
});
test('public API rejects empty and whitespace-only names', () => {
  for (const value of ['', ' ', '\t\n']) assert.throws(() => greet(value), TypeError);
});
test('CLI prints default and named greetings with successful exits', () => {
  for (const [args, expected] of [[[], 'Hello, world!\n'], [['Ada'], 'Hello, Ada!\n'], [['Ada Lovelace'], 'Hello, Ada Lovelace!\n']]) {
    const result = run(args);
    assert.equal(result.status, 0);
    assert.equal(result.stdout, expected);
    assert.equal(result.stderr, '');
  }
});
test('CLI help is stable and successful', () => {
  const result = run(['--help']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, usage);
  assert.equal(result.stderr, '');
});
test('CLI rejects unknown options and excess arguments with usage', () => {
  for (const args of [['--unknown'], ['-x'], ['--help', 'Ada'], ['Ada', 'Grace']]) {
    const result = run(args);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, usage);
  }
});
test('CLI reports blank names as errors with usage', () => {
  for (const value of ['', '   ']) {
    const result = run([value]);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, 'Name must not be blank\n' + usage);
  }
});

